// src/components/Projects.tsx
const Projects = () => {
  return (
    <section id="projects" className="py-20 px-6">
      <div className="max-w-6xl mx-auto">
        <h3 className="text-3xl font-semibold mb-8">Projects</h3>
        <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3].map((id) => (
            <div key={id} className="bg-gray-800 p-6 rounded-lg shadow hover:shadow-xl transition">
              <h4 className="text-xl font-bold mb-2">Project {id}</h4>
              <p className="text-gray-400">Short description of what the project does.</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Projects;
